 "methods": [
  {
   "title": "Survey-weighted models",
   "text": "Design-based variance by Taylor linearisation (NLSY97 strata and PSUs) or replicate weights (HSLS:09), validated against reference estimators and by simulation."
  },
  {
   "title": "Timing model",
   "text": "Support × age interaction; the age-16 vs age-12 contrast is tested for difference and for equivalence against a smallest effect size of interest."
  },
  {
   "title": "Missing data",
   "text": "Survey missing codes are kept by reason; multiple imputation (m = 40) pooled by Rubin's rules; complete-case sensitivity analysis."
  },
  {
   "title": "Multiplicity",
   "text": "One primary and one secondary confirmatory test (Holm). Everything else is labelled exploratory."
  },
  {
   "title": "Sensitivity",
   "text": "Age as categories, selection into co-residence, grade adjustment, alternative exposure codings, E-values for unmeasured confounding."
  },
  {
   "title": "Ethics",
   "text": "De-identified secondary data only; no microdata in the repository; small-cell suppression; no individual-level prediction or labelling."
  }
 ],
